function [r] = sat_dipole(m, m_max)
%SAT_DIPOLE  A dipole scaled down, its direction kept, until no axis passes m_max.
%   m: real[1][3] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   returns r: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = zeros(3, 1);
    a = 1;
    for i = (0):((3) - 1)
        d = asils.pc.fabs(m((i) + 1));
        if (d < 1e-30)
            d = 1e-30;
        end
        if ((m_max / d) < a)
            a = (m_max / d);
        end
    end
    r = (m * a);
end
